// createPhysicsBody puzzle
function createPhysicsBody(type, objSelector, shape, mass) {

    if (!window.Ammo || !_pGlob.world)
        return;

    var objNames = PzLib.retrieveObjectNames(objSelector);

    objNames.forEach(function(objName) {
        if (!objName)
            return;

        var obj = PzLib.getObjectByName(objName);
        if (!obj)
            return;

        PzLib.findAndRemovePhysicsBody(obj);

        switch (shape) {
        case 'BOX':
        case 'CAPSULE':
        case 'CONE':
        case 'CYLINDER':

            var box = new v3d.Box3();

            obj.resolveMultiMaterial().forEach(function(objR) {
                if (objR.geometry) {
                    if (objR.geometry.boundingBox == null)
                        objR.geometry.computeBoundingBox();

                    box.union(objR.geometry.boundingBox);
                }
            });

            var size = box.getSize(new v3d.Vector3());

            // do not allow empty-sized shapes
            size.x = size.x || 0.5;
            size.y = size.y || 0.5;
            size.z = size.z || 0.5;

            if (shape == 'BOX') {
                var geometry = new Ammo.btBoxShape(new Ammo.btVector3(
                        size.x * 0.5, size.y * 0.5, size.z * 0.5));
            } else if (shape == 'CAPSULE') {
                var radius = Math.max(size.x, size.z) * 0.5;
                var height = size.y - 2 * radius;
                var geometry = new Ammo.btCapsuleShape(radius, height);
            } else if (shape == 'CONE') {
                var radius = Math.max(size.x, size.z) * 0.5;
                var height = size.y;
                var geometry = new Ammo.btConeShape(radius, height);
            } else {
                var geometry = new Ammo.btCylinderShape(new Ammo.btVector3(
                        size.x * 0.5, size.y * 0.5, size.z * 0.5));
            }

            break;
        case 'SPHERE':

            var sphere = new v3d.Sphere();

            obj.resolveMultiMaterial().forEach(function(objR) {
                if (objR.geometry) {
                    // NOTE: by default spheres are based on boundings
                    // so always recalculate them here
                    objR.geometry.computeBoundingSphere();

                    if (sphere.isEmpty()) {
                        sphere.copy(objR.geometry.boundingSphere);
                    } else {
                        sphere.union(objR.geometry.boundingSphere);
                    }
                }
            });

            if (sphere.isEmpty()) {
                sphere.radius = 0.5;
            }

            var geometry = new Ammo.btSphereShape(sphere.isEmpty() ? 0.5 : sphere.radius);

            break;
        case 'MESH':

            var objsR = obj.resolveMultiMaterial();

            if (!objsR[0].geometry || !objsR[0].isMesh) {
                console.error('create rigid body puzzle: Incorrect mesh object');
                var geometry = new Ammo.btEmptyShape();
                break;
            }

            // allow complex triangle shapes for KINEMATIC objects
            if (type == 'DYNAMIC' || type == 'GHOST') {

                var geometry = new Ammo.btConvexHullShape();

                objsR.forEach(function(objR) {
                    var positions = objR.geometry.attributes.position.array;

                    for (var i = 0; i < positions.length; i+=3) {
                        var x = positions[i];
                        var y = positions[i+1];
                        var z = positions[i+2];

                        var v = new Ammo.btVector3(x, y, z);

                        geometry.addPoint(v);

                        Ammo.destroy(v);
                    }
                });

            } else {

                var triIdxVertArray = new Ammo.btTriangleMesh();

                objsR.forEach(function(objR) {
                    var positions = objR.geometry.attributes.position.array;
                    var indices = objR.geometry.index.array;

                    for (var i = 0; i < indices.length; i+=3) {

                        var i1 = indices[i];
                        var i2 = indices[i+1];
                        var i3 = indices[i+2];

                        var v1 = new Ammo.btVector3(positions[3*i1], positions[3*i1+1], positions[3*i1+2]);
                        var v2 = new Ammo.btVector3(positions[3*i2], positions[3*i2+1], positions[3*i2+2]);
                        var v3 = new Ammo.btVector3(positions[3*i3], positions[3*i3+1], positions[3*i3+2]);

                        triIdxVertArray.addTriangle(v1, v2, v3, false);

                        Ammo.destroy(v1);
                        Ammo.destroy(v2);
                        Ammo.destroy(v3);
                    }
                });

                var geometry = new Ammo.btBvhTriangleMeshShape(triIdxVertArray, true);

            }

            break;
        case 'EMPTY':
            var geometry = new Ammo.btEmptyShape();
            break;
        }

        var pos = obj.getWorldPosition(_pGlob.vec3Tmp);
        var quat = obj.getWorldQuaternion(_pGlob.quatTmp);

        var transform = new Ammo.btTransform();
        transform.setIdentity();
        transform.setOrigin(new Ammo.btVector3(pos.x, pos.y, pos.z));
        transform.setRotation(new Ammo.btQuaternion(quat.x, quat.y, quat.z, quat.w));
        var motionState = new Ammo.btDefaultMotionState(transform);

        if (type == 'STATIC' || type == 'KINEMATIC' || type == 'GHOST')
            var bodyMass = 0;
        else
            var bodyMass = mass;

        var localInertia = new Ammo.btVector3(0, 0, 0);
        geometry.calculateLocalInertia(bodyMass, localInertia);

        var rbInfo = new Ammo.btRigidBodyConstructionInfo(bodyMass, motionState, geometry, localInertia);
        var body = new Ammo.btRigidBody(rbInfo);

        // CF_STATIC_OBJECT is set automatically

        if (type == 'KINEMATIC' || type == 'GHOST') {
            body.setCollisionFlags(body.getCollisionFlags() | CF_KINEMATIC_OBJECT);
            body.setActivationState(DISABLE_DEACTIVATION);
        }

        if (type == 'GHOST') {

            body.setCollisionFlags(body.getCollisionFlags() | CF_NO_CONTACT_RESPONSE);
            _pGlob.world.addRigidBody(body, SensorTrigger, AllFilter);

        } else {

            _pGlob.world.addRigidBody(body);

        }


        //body.setDamping(0.1, 0.1);

        _pGlob.syncList.push({
            obj: obj,
            body: body,
            type: type,
            simulated: true,
            mass: mass
        });

        // external physics interface
        if (PL) {
            PL.physics.bodies[objName] = body;
        }
    });


}

// cloneAnimation puzzle
function cloneAnimation(animations, startFrame, endFrame) {

    if (!animations) {
        return;
    }

    // input can be either single obj or array of objects
    if (typeof animations === "string") {
        animations = [animations];
    }

    var newAnimations = animations.map(function(animName) {
        if (animName) {
            var sourceAction = v3d.SceneUtils.getAnimationActionByName(appInstance,
                    animName);
            if (sourceAction !== null) {
                var scene = PzLib.getSceneByAction(sourceAction);
                var frameRate = PzLib.getSceneAnimFrameRate(scene);

                var newClipName = PzLib.generateUniqueName(animName, function(name) {
                    return !PzLib.isClipNameUsed(name);
                });

                var newClip = v3d.AnimationUtils.subclip(sourceAction.getClip(),
                        newClipName, startFrame, endFrame, frameRate);
                const newAction = appInstance.mixer.clipAction(newClip, sourceAction.getRoot());

                newAction.setLoop(sourceAction.loop, sourceAction.repetitions, true);
                // COMPAT: always true since 4.10
                newAction.clampWhenFinished = true;
                appInstance.actions.push(newAction);
                return newClipName;
            }
        }

        return;
    });

    switch (newAnimations.length) {
        case 0:
            return;
        case 1:
            return newAnimations[0];
        default:
            return newAnimations;
    }
}

// dictSet puzzle
function dictSet(dict, key, value) {
    if (dict && typeof dict == 'object')
        dict[key] = value;
}

// checkVRMode puzzle
function checkVRMode(availableCb, unAvailableCb) {
    v3d.Detector.checkWebXR('immersive-vr', availableCb, unAvailableCb);
}

// createVector puzzle
function createVector(x, y, z) {
    return [x, y, z];
};

// getEventProperty puzzle
function getEventProperty(prop, event) {
    if (typeof event != "undefined") {
        switch (prop) {
            case 'target.checked':
                return event.target.checked;
            case 'target.id':
                return event.target.id;
            case 'target.value':
                return event.target.value;
            case 'touches.length':
                return event.touches ? event.touches.length : 0;
            case 'touches[0].pageX':
                return event.touches[0].pageX;
            case 'touches[0].pageY':
                return event.touches[0].pageY;
            case 'touches[1].pageX':
                return event.touches[1].pageX;
            case 'touches[1].pageY':
                return event.touches[1].pageY;
            case 'targetTouches.length':
                return event.targetTouches ? event.targetTouches.length : 0;
            case 'targetTouches[0].pageX':
                return event.targetTouches[0].pageX;
            case 'targetTouches[0].pageY':
                return event.targetTouches[0].pageY;
            case 'targetTouches[1].pageX':
                return event.targetTouches[1].pageX;
            case 'targetTouches[1].pageY':
                return event.targetTouches[1].pageY;
            default:
                return event[prop];
        }
    }
}

// eventHTMLElem puzzle
function eventHTMLElem(eventType, ids, isParent, callback) {
    var elems = PzLib.getElements(ids, isParent);
    for (var i = 0; i < elems.length; i++) {
        var elem = elems[i];
        if (!elem)
            continue;

        PzLib.bindListener(elem, eventType, callback);
    }
}

// Describe this function...
function init_kbm_controls() {
    keyboard_state = {};
    eventHTMLElem('keydown', ['DOCUMENT'], false, function(event) {
        dictSet(keyboard_state, getEventProperty('code', event), true);
    });
    eventHTMLElem('keyup', ['DOCUMENT'], false, function(event) {
        dictSet(keyboard_state, getEventProperty('code', event), false);
    });
    eventHTMLElem('mousedown', ['DOCUMENT'], false, function(event) {
        if (getEventProperty('button', event) == 0 || getEventProperty('button', event) == 2) {
            hand = getEventProperty('button', event) == 0 ? hand_left : hand_right;
            weapon = Weapon_get_first_colliding();
            if (weapon == null) {
                Hand_shoot(hand, Hand_character_calc_target_pos_non_vr, null);
            } else {
                Hand_pick_up_nearby_weapon(hand);
            }
        }
    });
    /* initialize movement condition */
    handle_movement_condition({});
    kbm_controls_before_sim(keyboard_state);
}

// xrSessionEvent puzzle
function xrSessionEvent(eventType, callback) {

    const eventHandler = function(event) {
        const ctrlObj = event.target;

        // set gamepad index to controller index
        _pGlob.gamepadIndex = appInstance.xrControllers.indexOf(ctrlObj);
        callback(event);

        // to cleanup XR controller rays/reticles
        if (event.type == 'disconnected') {
            _pGlob.objCache.clear();
        }
    }

    _pGlob.xrSessionCallbacks.push([eventType, eventHandler]);

    // register controller event here if executed after XR session acquisition
    if (_pGlob.xrSessionAcquired) {
        appInstance.xrControllers.forEach(function(controller) {
            PzLib.bindListener(controller, eventType, eventHandler);
        });
    }

}

// xrControllerProp puzzle
function xrControllerProp(prop) {

    if (_pGlob.xrSessionAcquired) {
        var controller = appInstance.xrControllers[_pGlob.gamepadIndex || 0];
        var inputSource = PzLib.xrGetInputSource(controller);
    } else {
        var controller = undefined;
        var inputSource = undefined;
    }

    switch (prop) {
    case 'OBJECT':
        if (controller)
            return controller.name;
        else
            return '';

    case 'RAY_RETICLE':
        if (controller && controller.children.length)
            return controller.children[0].name;
        else
            return '';

    case 'HANDEDNESS':
        if (controller && inputSource)
            return inputSource.handedness;
        else
            return '';

    case 'TARGET_RAY_MODE':
        if (controller && inputSource)
            return inputSource.targetRayMode;
        else
            return '';

    case 'PROFILES':
        if (controller && inputSource)
            return inputSource.profiles;
        else
            return [];

    case 'GAMEPAD_INDEX':
        if (controller && inputSource && inputSource.gamepad)
            return _pGlob.gamepadIndex || 0;
        else
            return 0;
    }

}

// getGamepadProp puzzle
function getGamepadProp(index, prop, controlIndex) {

    if (_pGlob.xrSessionAcquired) {
        var controller = appInstance.xrControllers[index];

        if (controller && controller.userData.inputSource &&
                controller.userData.inputSource.gamepad)
            var gamepad = controller.userData.inputSource.gamepad;
        else
            var gamepad = undefined;

    } else {
        var gamepad = navigator.getGamepads()[index];
    }

    switch (prop) {
    case 'AXIS':
        if (gamepad)
            return (gamepad.axes[controlIndex] || 0);
        else
            return 0;

    case 'BUTTON':
        if (gamepad) {
            var button = gamepad.buttons[controlIndex];

            if (button)
                return button.pressed;
            else
                return false;
        } else {
            return false;
        }

    case 'ANALOG_BUTTON':
        if (gamepad) {
            var button = gamepad.buttons[controlIndex];

            if (button)
                return button.value;
            else
                return 0.0;
        } else {
            return 0.0;
        }

    case 'ID':
        if (gamepad)
            return gamepad.id;
        else
            return '';

    case 'CONNECTION_STATUS':
        if (gamepad)
            return gamepad.connected;
        else
            return false;

    case 'TIMESTAMP':
        if (gamepad)
            return gamepad.timestamp;
        else
            return 0.0;

    case 'MAPPING':
        if (gamepad)
            return gamepad.mapping;
        else
            return '';

    case 'DEBUG_INFO':
        if (gamepad) {

            var axes = gamepad.axes;
            var axesValues = []

            for (var i = 0; i < axes.length; i++) {
                axesValues.push(Math.round(axes[i] * 1000) / 1000);
            }

            var buttons = gamepad.buttons;
            var btnsPressed = [];
            var btnsValues = [];

            for (var i = 0; i < buttons.length; i++) {
                btnsPressed.push(buttons[i].pressed ? '☑' : '☐');
                btnsValues.push(Math.round(buttons[i].value * 1000) / 1000);
            }

            return 'Index: ' + index + '\n' +
                   'Connected: ' + (gamepad.connected ? 'Yes' : 'No') + '\n' +
                   'ID: ' + (gamepad.id ? gamepad.id : 'N/A') + '\n' +
                   'Axes: ' + String(axesValues) + '\n' +
                   'Buttons: ' + String(btnsPressed) + '\n' +
                   'Analog Buttons: ' + String(btnsValues) + '\n' +
                   'Timestamp: ' + (gamepad.timestamp ? gamepad.timestamp.toFixed(3) : 0);
        } else {
            return 'Gamepad not available';
        }
    }

}

