// Describe this function...
function Weapon_play_animation_reload(weapon, finished_cb) {
    Weapon__stop_all_animations(weapon);
    if (dictGet(weapon, 'reload_animation') == null) {
        /* immediately call finished_cb */
        if (finished_cb != null) {
            finished_cb(weapon);
        }
    } else {
        operateAnimation('PLAY', dictGet(weapon, 'reload_animation'), null, null, 'LoopOnce', 1, function() {
            if (finished_cb != null) {
                finished_cb(weapon);
            }
        }, false);
    }
}

// Describe this function...
function Weapon__setup_collisions(weapon) {
    /* VR collisions */
    detectCollision(dictGet(weapon, 'collision_obj'), dictGet(hand_left, 'collision_obj'), function() {
        if (game_mode == 'VR') {
            /* Can pick weapons that lay around and the weapon from the other hand */
            Weapon__update_colliding_weapons_list(Weapon__colliding_weapons_vr_hand_left, weapon, !dictGet(weapon, '_is_wielded') || weapon != dictGet(hand_left, 'weapon'));
        }
    }, function() {
        if (game_mode == 'VR') {
            Weapon__update_colliding_weapons_list(Weapon__colliding_weapons_vr_hand_left, weapon, false);
        }
    });
    detectCollision(dictGet(weapon, 'collision_obj'), dictGet(hand_right, 'collision_obj'), function() {
        if (game_mode == 'VR') {
            /* Can pick weapons that lay around and the weapon from the other hand */
            Weapon__update_colliding_weapons_list(Weapon__colliding_weapons_vr_hand_right, weapon, !dictGet(weapon, '_is_wielded') || weapon != dictGet(hand_right, 'weapon'));
        }
    }, function() {
        if (game_mode == 'VR') {
            Weapon__update_colliding_weapons_list(Weapon__colliding_weapons_vr_hand_right, weapon, false);
        }
    });
    /* NON-VR collisions */
    detectCollision(dictGet(weapon, 'collision_obj'), 'character_enemy_trigger', function() {
        if (game_mode == 'NO_VR') {
            /* Can only pick up weapons that lay around, not the wielded ones */
            Weapon__update_colliding_weapons_list(Weapon__colliding_weapons, weapon, !dictGet(weapon, '_is_wielded'));
        }
    }, function() {
        if (game_mode == 'NO_VR') {
            Weapon__update_colliding_weapons_list(Weapon__colliding_weapons, weapon, false);
        }
    });
}

