// Describe this function...
function init_touch_controls_left(touch_controls_state) {
    eventHTMLElem('touchstart', 'left-part-div', false, function(event) {
        base_touch_x_1 = getEventProperty('targetTouches[0].pageX', event);
        base_touch_y_1 = getEventProperty('targetTouches[0].pageY', event);
        setHTMLElemStyle('left', String(base_touch_x_1) + 'px', 'movement-div', false);
        setHTMLElemStyle('top', String(base_touch_y_1) + 'px', 'movement-div', false);
        setHTMLElemStyle('display', 'block', 'movement-div', false);
        setHTMLElemStyle('height', '60px', 'movement-div', false);
    });
    eventHTMLElem('touchmove', 'left-part-div', false, function(event) {
        current_touch_y_1 = getEventProperty('targetTouches[0].pageY', event);
        length_touch_y_1 = base_touch_y_1 - current_touch_y_1;
        if (length_touch_y_1 >= Mobile_LEFT_PAN_THRESHOLD_SHORT) {
            setHTMLElemStyle('height', String(length_touch_y_1 + 30) + 'px', 'movement-div', false);
            setHTMLElemStyle('marginTop', String(-length_touch_y_1) + 'px', 'movement-div', false);
        } else if (length_touch_y_1 < -Mobile_LEFT_PAN_THRESHOLD_SHORT) {
            setHTMLElemStyle('height', String(Math.abs(length_touch_y_1) + 30) + 'px', 'movement-div', false);
        }
        _clear_touch_controls_state_left(touch_controls_state);
        if (length_touch_y_1 >= Mobile_LEFT_PAN_THRESHOLD_SHORT && length_touch_y_1 < Mobile_LEFT_PAN_THRESHOLD_LONG) {
            dictSet(touch_controls_state, 'left_pan_up', true);
            setHTMLElemStyle('backgroundColor', '#19de3d', 'movement-div', false);
        } else if (length_touch_y_1 >= Mobile_LEFT_PAN_THRESHOLD_LONG) {
            dictSet(touch_controls_state, 'left_pan_up_long', true);
            setHTMLElemStyle('backgroundColor', '#EED944', 'movement-div', false);
        } else if (length_touch_y_1 <= -Mobile_LEFT_PAN_THRESHOLD_SHORT && length_touch_y_1 > -Mobile_LEFT_PAN_THRESHOLD_LONG) {
            dictSet(touch_controls_state, 'left_pan_down', true);
            setHTMLElemStyle('backgroundColor', '#52AFF3', 'movement-div', false);
        } else if (length_touch_y_1 <= -Mobile_LEFT_PAN_THRESHOLD_LONG) {
            dictSet(touch_controls_state, 'left_pan_down_long', true);
            setHTMLElemStyle('backgroundColor', '#EED944', 'movement-div', false);
        }
    });
    eventHTMLElem('touchend', 'left-part-div', false, function(event) {
        setHTMLElemStyle('display', 'none', 'movement-div', false);
        setHTMLElemStyle('marginTop', '-30px', 'movement-div', false);
        setHTMLElemStyle('backgroundColor', 'red', 'movement-div', false);
        _clear_touch_controls_state_left(touch_controls_state);
    });
}

